{
  "pains": [
    {
      "id": "pain:state-letters-for-taxes-i-paid-for",
      "statement": "I pay Gusto to file my taxes, and then a letter from the state shows up saying a quarter was never filed and I owe penalties, and now that's my problem to fix.",
      "element": "b2b:ease_of_doing_business:risk_reduction",
      "shape": {
        "surface": "A letter from the state unemployment or revenue agency: a missed quarterly report, an unpaid SUI balance, a rate jump, penalties and interest.",
        "operational": "The owner calls the agency, files the notice with Gusto, chases support for weeks, and is told to hire a CPA or pay the overdue amount themselves.",
        "personal": "Thousands of dollars in penalties on a small business, and 'very scary letters' that the owner has to sort out alone after paying someone to take this off their plate."
      },
      "workflow": "Gusto runs payroll and is supposed to file the state quarterly wage report and SUI payment; the break shows months later when the state agency (e.g. the Department of Unemployment) mails a delinquency notice and the owner uploads it to Gusto's tax notice flow and waits.",
      "type": "felt",
      "confidence": "medium",
      "priority": 1,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Owners posted dated 1-star reviews in September and October 2026 about missed state filings and the penalties that followed.",
        "cites": ["src:3"]
      },
      "triggers": [
        {
          "event": "A seasonal quarter with no wages: no zero-wage report gets filed and the state marks the business delinquent.",
          "cites": ["src:9"]
        },
        {
          "event": "A tax notice arrives in the mail and needs a response by the agency's deadline.",
          "cites": ["src:2"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "An error led to Gusto not paying State Unemployment taxes.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I started to receive very scary letters from the Department of Unemployment, saying that I owe over $7K.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "their mistakes have cost me thousands of dollars in penalties, interest, and fees.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Gusto did not file a quarterly wage report, so even though I owed nothing I was delinquent.",
              "cites": ["src:9"]
            }
          ],
          "costs_them": "Penalties and interest in the thousands, plus their own hours on the phone with the state.",
          "fears": "That a tax they paid for was never filed and they will not find out until the state's letter arrives.",
          "dream_outcome": "Taxes filed on time every quarter without having to think about it."
        }
      },
      "relief": {
        "line": "Taxes just go out. Every quarter is filed and paid on time and the mailbox stays quiet.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "the platform has been a saving grace in making payroll, payroll tax, and unemployment insurance compliance easy",
            "cites": ["src:7"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Taxes stop being their problem. Payroll becomes the thing they hold up as how every other back-office tool should work.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "I am a HUGE fan of the way Gusto handles payroll and all the different taxes and form filing for me",
            "cites": ["src:10"]
          },
          {
            "role": "economic_buyer",
            "verbatim": "in the same way that my Gusto payroll runs automatically",
            "cites": ["src:11"]
          }
        ],
        "gap": null
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": "feat:payroll",
      "feature_note": "Payroll's tax filing is both what kills this pain and what causes it when a filing gets missed; the complaints are about Gusto's own misses.",
      "cites": ["src:3", "src:1", "src:9"]
    },
    {
      "id": "pain:no-one-who-can-fix-it",
      "statement": "When something actually goes wrong, I call five times, get a new rep every time, and nobody who can fix it ever calls me back.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "Tickets that sit for weeks, reps who relay messages, promised callbacks that never come.",
        "operational": "Repeated calls and chats, re-explaining the issue to each new rep, working directly with the insurer or state instead, or having the bookkeeper call on the owner's behalf.",
        "personal": "Owners call it infuriating; one says a response 'makes me furious', and long-time customers start planning to leave."
      },
      "workflow": "After a tax notice, a benefits error or a bad W-2 in Gusto, the owner or their bookkeeper opens chat or calls Gusto support, gets passed between reps, and waits on a specialist team that does not call back.",
      "type": "felt",
      "confidence": "medium",
      "priority": 2,
      "felt_evidence": {
        "kind": "switching",
        "what": "A long-time customer wrote in February 2026 that bad support means they will likely switch payroll/HR software later this year.",
        "cites": ["src:2"]
      },
      "triggers": [
        {
          "event": "A regulatory tax notice that the owner needs Gusto's help to answer.",
          "cites": ["src:2"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "It takes at least five calls to get anything taken care of.",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "my inquiries just disappear into a black box.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "The support reps function strictly as a go-between",
              "cites": ["src:2"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "are most likely going to be switching to another payroll/HR software later this year.",
              "cites": ["src:2"]
            }
          ],
          "costs_them": "Weeks of calls on one issue, and the original problem (a notice, a benefit, a W-2) staying open the whole time.",
          "fears": "That an open tax or benefits problem gets worse while nobody owns it.",
          "dream_outcome": "One person who knows their account and can fix the problem on the first call."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Long hold times, call centers close at 3 pm if you are on the west coast",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "The bookkeeper's billable time on hold across every client they moved to Gusto.",
          "fears": "No source shows the fear; the one quote stops at the cost.",
          "dream_outcome": "Support that is open when they work and fixes client issues fast."
        }
      },
      "relief": {
        "line": "Someone picks up. Support answers fast and knows the platform.",
        "says": [
          {
            "role": "end_user",
            "verbatim": "Customer service is spot on, platform is one of the most user friendly platforms I have seen",
            "cites": ["src:4"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "A support team they trust. They send their own clients there.",
        "says": [],
        "gap": "Read the Trustpilot 'peace of mind' 5-star filter and the bookkeeper filter; reviews describe responsive support, none describes a lasting change in standing from it."
      },
      "segments": ["seg:micro", "seg:smb", "seg:accountants"],
      "feature_ref": null,
      "feature_note": "No feature in brain/company covers support. What would: a named account owner or a tax-resolution team with a callback commitment.",
      "cites": ["src:1", "src:2", "src:4"]
    },
    {
      "id": "pain:payday-and-no-deposits",
      "statement": "I submitted payroll days early, and on Friday none of my staff got paid, so I'm handing out cash from the register so they can make rent.",
      "element": "b2b:individual:reputational_assurance",
      "shape": {
        "surface": "Payday arrives and direct deposits have not landed, or Gusto blocks or reschedules the payroll.",
        "operational": "The owner pays the team by hand: cash from the till, Venmo, CashApp or paper checks, then chases Gusto for where the money went.",
        "personal": "Facing staff who cannot pay rent, and in one case losing an employee over it."
      },
      "workflow": "The owner submits payroll in Gusto ahead of the deadline; on payday morning employees report no direct deposit, and the owner calls support while paying people from the shop's cash register.",
      "type": "felt",
      "confidence": "medium",
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Owners posted dated reviews in July and August 2026 about payrolls that failed to deposit on time.",
        "cites": ["src:5"]
      },
      "triggers": [
        {
          "event": "Gusto blocks or reschedules a submitted payroll before payday.",
          "cites": ["src:5"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "none of my baristas got their direct deposits.",
              "cites": ["src:5"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I had to pay people out of the shop",
              "cites": ["src:5"]
            },
            {
              "situation": "venting",
              "verbatim": "Incompetent service caused a missed payroll and lost me an employee.",
              "cites": ["src:2"]
            },
            {
              "situation": "venting",
              "verbatim": "They will block your payroll and you could ultimately have no control over paying your employees",
              "cites": ["src:5"]
            }
          ],
          "costs_them": "Cash on hand on payday, and the trust of staff who were not paid.",
          "fears": "Losing employees who cannot count on being paid on time.",
          "dream_outcome": "Every payday, everyone is paid on time without the owner touching it."
        }
      },
      "relief": {
        "line": "Payday is boring. Everyone gets paid and nobody texts the owner.",
        "says": [],
        "gap": "Read the Trustpilot 'direct deposit' filter; the only on-time praise came from an employee, not an owner."
      },
      "euphoria": {
        "line": "The owner who always pays on time. Staff stay because payday never slips.",
        "says": [],
        "gap": "No owner source describes the year after; searched the direct deposit and 'peace of mind' filters."
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": "feat:payroll",
      "cites": ["src:5", "src:2"]
    },
    {
      "id": "pain:new-state-new-paperwork",
      "statement": "The moment someone works from another state, I'm registering with that state, sometimes the city too, and fighting their agency for months even though Gusto runs my payroll.",
      "element": "b2b:ease_of_doing_business:reduced_effort",
      "shape": {
        "surface": "New state withholding and unemployment accounts to open, letters with account numbers, local registrations, wages filed to the wrong state.",
        "operational": "The owner registers with each state and city themselves or pays a partner service (Middesk) to do it, then fights the state to move wages after an employee relocates.",
        "personal": "Months of the owner's time; one describes a seven-month battle with the state."
      },
      "workflow": "An employee is hired in or moves to a new state; before Gusto can run payroll there, the owner opens state withholding and SUI accounts (and city or metro registrations), enters the IDs in Gusto, and later reconciles wages filed to the old state.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "paying",
        "what": "An owner paid Gusto's suggested partner Middesk to handle state tax and UI registration.",
        "cites": ["src:3"]
      },
      "triggers": [
        {
          "event": "An employee relocates to another state mid-year.",
          "cites": ["src:3"]
        },
        {
          "event": "A first remote hire in a state like California, which forces foreign-entity registration.",
          "cites": ["src:12"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "have to spend a not-insignificant amount of time wrestling with each state",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "Plus there are a growing number of cities or metros that you have to register with as well.",
              "cites": ["src:8"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I had two employees move from Utah to Massachusetts in September 2025.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I ended up in a SEVEN MONTH LONG battle with the state to transfer their wages.",
              "cites": ["src:3"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "In CA, which is probably one of the most draconian, we had to register as a foreign entity",
              "cites": ["src:12"]
            }
          ],
          "costs_them": "Hours per state at setup and months of back-and-forth when an employee moves.",
          "fears": "No source shows the fear directly; the quotes stop at time and the fight with the state.",
          "dream_outcome": "Hire anyone anywhere and have the state accounts just exist."
        }
      },
      "relief": {
        "line": "New state, same payroll. The accounts are open before the first paycheck.",
        "says": [],
        "gap": "Read the Trustpilot state filter and HN threads on remote hiring; nobody describes the after-state."
      },
      "euphoria": {
        "line": "Hiring stops being limited by where people live.",
        "says": [],
        "gap": "No source found; same searches as relief."
      },
      "segments": ["seg:smb"],
      "feature_ref": null,
      "feature_note": "No brain/company feature covers state registration; Gusto routes it to the partner Middesk per one review. A built-in registration service would kill it.",
      "cites": ["src:8", "src:3", "src:12"]
    },
    {
      "id": "pain:rate-went-up-without-telling-me",
      "statement": "My Gusto bill keeps creeping up, they doubled my rate without notice, and they still charge a full month when I cancel.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "A higher monthly charge, new add-on fees, or a full month billed after cancelling.",
        "operational": "The owner audits invoices, calls to get the old rate back, or moves payroll to ADP, QuickBooks Payroll or SurePayroll.",
        "personal": "Feeling played: one owner says the increase came 'hoping I wouldn't notice'."
      },
      "workflow": "The monthly Gusto invoice on the company card, at renewal or after a promo ends, when the owner compares it to last year's charge.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "switching",
        "what": "A 15-employee company said it was switching to ADP after a fee increase; another moved to QuickBooks Payroll.",
        "cites": ["src:6"]
      },
      "triggers": [
        {
          "event": "Renewal after a first year or the end of a promo price.",
          "cites": ["src:6"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "Doubled my monthly rate without notice.",
              "cites": ["src:2"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Long story short, Gusto has upped my subscription by $40/mo. over 16 months",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "It was initially very affordable but became more and more expensive.",
              "cites": ["src:6"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "We have 15 employees and will be switching to ADP today.",
              "cites": ["src:6"]
            },
            {
              "situation": "venting",
              "verbatim": "Gusto recently doubled their prices",
              "cites": ["src:13"]
            }
          ],
          "costs_them": "Tens of dollars a month more than they signed up for, compounding each year.",
          "fears": "That the price will keep rising quietly.",
          "dream_outcome": "One predictable price, with notice before it changes."
        }
      },
      "relief": {
        "line": "A fair price. The bill matches what they expected.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "The solutions are relevant and the pricing is fair.",
            "cites": ["src:7"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Payroll costs stop being something they check.",
        "says": [],
        "gap": "Read the Trustpilot price filter and 'peace of mind' 5-star filter; no lasting after-state described."
      },
      "segments": ["seg:micro", "seg:smb"],
      "feature_ref": null,
      "feature_note": "A pricing-policy pain, not a feature gap: a price lock or advance notice would fix it. Close to an acceptable_price objection for positioning.",
      "cites": ["src:6", "src:2", "src:13"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Owners name and compare specific payroll providers (ADP, QuickBooks Payroll, SurePayroll, Paychex) when switching, so they know solutions exist.",
      "cites": ["src:6", "src:7"]
    }
  },
  "stats": [],
  "keywords": [
    "payroll company did not file state unemployment taxes",
    "state unemployment tax notice penalty payroll provider",
    "direct deposit did not go through payday payroll",
    "register employer state withholding remote employee",
    "payroll company raised prices without notice"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the last ten sales calls, which problem did the prospect name first: tax filing mistakes, support, payday reliability, multi-state setup or price?",
      "why": "Priority here comes from public complaints by existing users, not from what prospects say before buying.",
      "would_change": "pains[].priority"
    },
    {
      "id": "q:pains-accountants",
      "question": "What do the accountants and bookkeepers who run payroll for your clients complain about most when they work in Gusto?",
      "why": "Only one public source spoke as a bookkeeper running payroll for clients; the accountant segment is barely covered.",
      "would_change": "pains[].segments, pains[].by_role.end_user"
    },
    {
      "id": "q:pains-churn-reason",
      "question": "When customers churn, which reason do they give most: a tax or filing error, support, a price change, or a failed payroll?",
      "why": "The map leans on 1-2 star Trustpilot reviews; churn data would show which pain actually costs customers.",
      "would_change": "pains[].priority, pains[].confidence"
    },
    {
      "id": "q:pains-micro-diy",
      "question": "For owners with under 10 employees who still run payroll by hand, what finally makes them buy software?",
      "why": "No source showed the do-it-yourself owner's pain before buying; every source was an existing payroll user.",
      "would_change": "pains, awareness.seg:micro"
    }
  ],
